export function asciiString(
  str: string,
  charMap: Record<any, any> = asciiCharMap
) {
  // Normalize NFD chars to NFC
  str = str.normalize('NFC');

  let asciiStr = '';
  let char;

  for (let i = 0; i < str.length; i++) {
    char = str.charAt(i);
    asciiStr += typeof charMap[char] === 'string' ? charMap[char] : char;
  }

  return asciiStr;
}

export function toHandle(
  value: string,
  options:
    | {
        allowNonAlphaStart: boolean;
        handleCasing: 'snake' | 'pascal' | 'camel';
      }
    | {} = {}
) {
  const settings = {
    allowNonAlphaStart: false,
    handleCasing: 'camel',
    ...options,
  };

  // Remove HTML tags
  var handle = value.replace(/<(.*?)>/g, '');

  // Remove inner-word punctuation
  handle = handle.replace(/['"‘’“”ʻ\[\]\(\)\{\}:]/g, '');

  // Make it lowercase
  handle = handle.toLowerCase();

  // Convert extended ASCII characters to basic ASCII
  handle = asciiString(handle);

  if (!settings.allowNonAlphaStart) {
    // Handle must start with a letter
    handle = handle.replace(/^[^a-z]+/, '');
  }

  // Get the "words"
  let words = handle.split(/[^a-z0-9]+/).filter(Boolean);
  handle = '';

  if (settings.handleCasing === 'snake') {
    return words.join('_');
  }

  // Make it camelCase
  for (let i = 0; i < words.length; i++) {
    if (settings.handleCasing !== 'pascal' && i === 0) {
      handle += words[i];
    } else {
      handle += words[i]!.charAt(0).toUpperCase() + words[i]!.substring(1);
    }
  }

  return handle;
}

export function toEnvVar(
  value: string,
  options:
    | {
        prefix: string;
        suffix: string;
      }
    | {} = {}
) {
  const settings = {
    prefix: '',
    suffix: '',
    ...options,
  };

  let name = toHandle(value, {handleCasing: 'snake'}).toUpperCase();
  return name ? `${settings.prefix}${name}${settings.suffix}` : '';
}

/**
 * Converts a string to a URI-friendly slug format.
 */
export function toUriFormat(value: string): string {
  // Remove HTML tags
  let str = value.replace(/<(.*?)>/g, '');

  // Make it lowercase
  str = str.toLowerCase();

  // Convert extended ASCII characters to basic ASCII
  str = asciiString(str);

  // Must start with a letter and end with a letter/number
  str = str.replace(/^[^a-z]+/, '');
  str = str.replace(/[^a-z0-9]+$/, '');

  // Get the "words"
  const words = str.split(/[^a-z0-9]+/).filter(Boolean);

  return words.join('-');
}

export function capitalize(str: string): string {
  return str.charAt(0).toUpperCase() + str.slice(1);
}

export function rand() {
  return Math.floor(Math.random() * 1000000);
}
